Q: Working with multiple checkboxes in Nextjs14, zod, shadcn/ui and react-hook-form A: <p>Below is a <strong>complete, runnable, and safe example</strong> for handling <strong>multiple checkboxes in Next.js</strong> to perform a <strong>bulk update</strong> (e.g., updating multiple items at once).<br />
This example uses:</p>
<p>• Next.js App Router<br />
• React server + client components<br />
• TypeScript<br />
• A mock async API (can easily be replaced with a real DB/prisma endpoint)<br />
• Full input validation &amp; error handling</p>
<hr />
<h2>1) Client Component (with multiple checkboxes + bulk action)</h2>
<pre><code>&quot;use client&quot;;

import { useState } from &quot;react&quot;;

type Item = {
  id: number;
  name: string;
  status: string;
};

interface Props {
  items: Item[];
}

export default function ItemList({ items }: Props) {
  // Track selected IDs
  const [selected, setSelected] = useState&lt;number[]&gt;([]);
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState(&quot;&quot;);

  // Toggle checkbox
  const toggleSelect = (id: number) =&gt; {
    setSelected((prev) =&gt;
      prev.includes(id) ? prev.filter((i) =&gt; i !== id) : [...prev, id]
    );
  };

  // Bulk update action
  const bulkUpdate = async () =&gt; {
    setErrorMsg(&quot;&quot;);

    if (selected.length === 0) {
      setErrorMsg(&quot;Please select at least one item.&quot;);
      return;
    }

    try {
      setLoading(true);

      const res = await fetch(&quot;/api/bulk-update&quot;, {
        method: &quot;POST&quot;,
        headers: { &quot;Content-Type&quot;: &quot;application/json&quot; },
        body: JSON.stringify({ ids: selected })
      });

      if (!res.ok) {
        throw new Error(&quot;Failed to update items.&quot;);
      }

      alert(&quot;Bulk update successful.&quot;);
    } catch (err: any) {
      setErrorMsg(err.message || &quot;Unexpected error.&quot;);
    } finally {
      setLoading(false);
    }
  };

  return (
    &lt;div style={{ maxWidth: 400 }}&gt;
      &lt;h2&gt;Items&lt;/h2&gt;

      {items.map((item) =&gt; (
        &lt;div key={item.id} style={{ marginBottom: 8 }}&gt;
          &lt;label&gt;
            &lt;input
              type=&quot;checkbox&quot;
              checked={selected.includes(item.id)}
              onChange={() =&gt; toggleSelect(item.id)}
            /&gt;
            {item.name} (status: {item.status})
          &lt;/label&gt;
        &lt;/div&gt;
      ))}

      {errorMsg &amp;&amp; (
        &lt;p style={{ color: &quot;red&quot;, marginTop: 10 }}&gt;{errorMsg}&lt;/p&gt;
      )}

      &lt;button onClick={bulkUpdate} disabled={loading}&gt;
        {loading ? &quot;Updating...&quot; : &quot;Bulk Update Selected&quot;}
      &lt;/button&gt;
    &lt;/div&gt;
  );
}
</code></pre>
